// RP1 PIO: DMA one 32-bit word per clock, containing the default pinout's
// 18 RGB bits. GPIO17 CLK is generated by side-set. NOT a HUB75 scan program.
// DISCONNECT PANELS: latch/address are not driven; OE is kept HIGH (blanked).
#define _POSIX_C_SOURCE 200809L
#include <errno.h>
#include <fcntl.h>
#include <inttypes.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <time.h>
#include <unistd.h>
#include <misc/rp1_pio_if.h>

#define CLK_PIN 17u
#define OE_PIN 18u
#define CLK_MASK (1u << CLK_PIN)
#define OE_MASK (1u << OE_PIN)

// From the default HZELLER_HAT pinout in include/rpihub75.h (three ports).
// Not compatible with ADA_HAT or a custom pinout.
static const unsigned data_pins[] = {
    27, 9, 7, 10, 11, 8,     // port 0: G1 G2 B1 B2 R1 R2
    5, 13, 6, 20, 12, 19,   // port 1
    14, 26, 2, 16, 3, 21    // port 2: R1 R2 G1 G2 B1 B2
};

static volatile sig_atomic_t stop;
static void on_signal(int sig) { (void)sig; stop = 1; }

static double now_seconds(void)
{
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return (double)t.tv_sec + t.tv_nsec * 1e-9;
}

static int command(int fd, unsigned long code, void *arg, const char *label)
{
    if (ioctl(fd, code, arg) >= 0) return 0;
    fprintf(stderr, "%s: %s (%d)\n", label, strerror(errno), errno);
    return -1;
}

static int number(const char *s, unsigned max, unsigned *result)
{
    char *end;
    errno = 0;
    unsigned long v = strtoul(s, &end, 10);
    if (errno || s == end || *end || v < 1 || v > max) return -1;
    *result = (unsigned)v;
    return 0;
}

int main(int argc, char **argv)
{
    unsigned duration = 5, divider = 4, kib = 256;
    int output = 0, light_dma = 0;
    int narg = argc;
    while (narg > 1) {
        if (!output && strcmp(argv[narg - 1], "--output") == 0) {
            output = 1; --narg;
        } else if (!light_dma && strcmp(argv[narg - 1], "--light-dma") == 0) {
            light_dma = 1; --narg;
        } else {
            break;
        }
    }
    int no_pins = !output; // safe by default; GPIO must be explicitly requested
    unsigned *fields[] = { &duration, &divider, &kib };
    unsigned limits[] = { 3600, 65535, 1024 };
    if (narg > 4) goto usage;
    for (int i = 1; i < narg; ++i)
        if (number(argv[i], limits[i - 1], fields[i - 1])) goto usage;

    uint32_t data_mask = 0;
    for (size_t i = 0; i < sizeof(data_pins) / sizeof(data_pins[0]); ++i)
        data_mask |= 1u << data_pins[i];
    const uint32_t output_mask = data_mask | CLK_MASK | OE_MASK;
    const size_t bytes = (size_t)kib * 1024;
    uint32_t *data = aligned_alloc(64, bytes);
    if (!data) { perror("aligned_alloc"); return 1; }
    for (size_t i = 0; i < bytes / sizeof(*data); ++i)
        data[i] = OE_MASK | ((i & 1u) ? data_mask : 0);

    struct sigaction action = { .sa_handler = on_signal };
    sigemptyset(&action.sa_mask);
    sigaction(SIGINT, &action, NULL);
    sigaction(SIGTERM, &action, NULL);
    int fd = open("/dev/pio0", O_RDWR);
    if (fd < 0) { perror("open /dev/pio0"); free(data); return 1; }
    int result = 1, sm = -1, claimed = 0, loaded = 0, initialized = 0;
    uint32_t muxed_mask = 0;
    struct rp1_pio_sm_claim_args claim = {0};
    for (int i = 0; i < RP1_PIO_SM_COUNT; ++i) {
        claim.mask = 1u << i;
        if (ioctl(fd, PIO_IOC_SM_CLAIM, &claim) == 0) {
            sm = i; claimed = 1; break;
        }
    }
    if (sm < 0) { fputs("No free PIO state machine\n", stderr); goto done; }

    // Explicit PULL (blocks if DMA starves), OUT PINS,28 (or OUT NULL,28),
    // NOP side 1. All other instructions have side 0. Each rising edge
    // follows a fresh DMA word; no FIFO word is reused on an underflow.
    struct rp1_pio_add_program_args program = {
        .num_instrs = 3, .origin = RP1_PIO_ORIGIN_ANY,
        .instrs = { 0x80a0, no_pins ? 0x607c : 0x601c, 0xb042 }
    };
    int origin = ioctl(fd, PIO_IOC_ADD_PROGRAM, &program);
    if (origin < 0) { perror("ADD_PROGRAM"); goto done; }
    program.origin = (uint16_t)origin;
    loaded = 1;

    struct rp1_pio_sm_init_args init = {
        .sm = (uint16_t)sm, .initial_pc = program.origin,
        .config = {
            .clkdiv = divider << 16,
            .execctrl = ((uint32_t)(program.origin + 2) << 12) |
                        ((uint32_t)program.origin << 7),
            .shiftctrl = (1u << 30) | (1u << 19), // TX join; shift right
            .pinctrl = (28u << 20) | (1u << 29) | (CLK_PIN << 10)
        }
    };
    if (command(fd, PIO_IOC_SM_INIT, &init, "SM_INIT")) goto done;
    initialized = 1;
    // A newly claimed SM can retain FIFO/shift-register state from its prior
    // owner. Reset only this SM, never the other three state machines.
    struct rp1_pio_sm_clear_fifos_args clear = { .sm = (uint16_t)sm };
    if (command(fd, PIO_IOC_SM_CLEAR_FIFOS, &clear, "CLEAR_FIFOS")) goto done;
    struct rp1_pio_sm_restart_args restart = { .mask = (uint16_t)(1u << sm) };
    if (command(fd, PIO_IOC_SM_RESTART, &restart, "SM_RESTART")) goto done;
    if (light_dma) {
        // Kernel selects txNl and configures matching FIFO DREQ watermark.
        // Never raise the heavy channel's watermark by hand: its 8-word
        // bursts could overflow the 8-word PIO FIFO.
        struct rp1_pio_sm_config_xfer_v2_args cfg = {
            .sm = (uint16_t)sm, .dir = RP1_PIO_DIR_TO_SM,
            .flags = RP1_PIO_SM_CONFIG_XFER_FL_DMA_FORCE_LIGHT,
            .buf_size = (uint32_t)bytes, .buf_count = 4
        };
        if (command(fd, PIO_IOC_SM_CONFIG_XFER_V2, &cfg,
                    "CONFIG_XFER_V2 light DMA (kernel may not support it)")) goto done;
    } else {
        struct rp1_pio_sm_config_xfer32_args cfg = {
            .sm = (uint16_t)sm, .dir = RP1_PIO_DIR_TO_SM,
            .buf_size = (uint32_t)bytes, .buf_count = 4
        };
        if (command(fd, PIO_IOC_SM_CONFIG_XFER32, &cfg, "CONFIG_XFER32")) goto done;
    }
    struct rp1_pio_sm_get_dmactrl_args dmactrl = {
        .sm = (uint16_t)sm, .is_tx = 1
    };
    if (!command(fd, PIO_IOC_SM_GET_DMACTRL, &dmactrl, "GET_DMACTRL"))
        printf("TX DMACTRL: 0x%08x (low bits: DREQ threshold)\n", dmactrl.ctrl);

    if (!no_pins) {
        fprintf(stderr, "WARNING: disconnect panels! 18 RGB pins + GPIO17 CLK toggle; OE18 stays HIGH.\n");
        struct rp1_pio_sm_set_pins_args initial = {
            .sm = (uint16_t)sm, .values = OE_MASK, .mask = output_mask
        };
        if (command(fd, PIO_IOC_SM_SET_PINS, &initial, "SET_PINS initial")) goto done;
        for (unsigned pin = 0; pin < RP1_PIO_GPIO_COUNT; ++pin) {
            if (!(output_mask & (1u << pin))) continue;
            struct rp1_gpio_init_args gpio = { .gpio = (uint16_t)pin };
            if (command(fd, PIO_IOC_GPIO_INIT, &gpio, "GPIO_INIT")) goto done;
            muxed_mask |= 1u << pin;
            struct rp1_gpio_set_function_args fn = {
                .gpio = (uint16_t)pin, .fn = RP1_GPIO_FUNC_PIO
            };
            if (command(fd, PIO_IOC_GPIO_SET_FUNCTION, &fn, "GPIO_SET_FUNCTION PIO")) goto done;
        }
        struct rp1_pio_sm_set_pindirs_args dir = {
            .sm = (uint16_t)sm, .dirs = output_mask, .mask = output_mask
        };
        if (command(fd, PIO_IOC_SM_SET_PINDIRS, &dir, "SET_PINDIRS output")) goto done;
    }
    struct rp1_pio_sm_set_enabled_args enable = {
        .mask = (uint16_t)(1u << sm), .enable = 1
    };
    if (command(fd, PIO_IOC_SM_SET_ENABLED, &enable, "SET_ENABLED")) goto done;

    printf("RP1 PIO SM%d: %s; %s, data mask=0x%08x\n"
           "Divider %u; PIO ceiling %.2f MHz; %s DMA, one word per rising edge; %zu KiB/transfer, %u s\n",
           sm, no_pins ? "PULL + OUT NULL,28 (no pins driven)" : "PULL + OUT PINS,28 + side-set CLK",
           no_pins ? "no physical CLK/OE" : "CLK=GPIO17, OE=GPIO18 HIGH",
           data_mask, divider, 200.0 / divider / 3,
           light_dma ? "light" : "default", bytes / 1024, duration);
    fflush(stdout);
    double start = now_seconds(), last = start;
    uint64_t transfers = 0, prior = 0;
    while (!stop && now_seconds() - start < duration) {
        struct rp1_pio_sm_xfer_data32_args xfer = {
            .sm = (uint16_t)sm, .dir = RP1_PIO_DIR_TO_SM,
            .data_bytes = (uint32_t)bytes, .data = data
        };
        if (ioctl(fd, PIO_IOC_SM_XFER_DATA32, &xfer) < 0) {
            if (errno == EINTR && stop) break;
            fprintf(stderr, "XFER_DATA32: %s (%d)\n", strerror(errno), errno);
            goto done;
        }
        ++transfers;
        double now = now_seconds();
        if (now - last >= 1.0) {
            printf("%.2f s: %.2f Mword/s (~%.2f MHz CLK average), %" PRIu64 " transfers\n",
                   now - start, (transfers - prior) * (bytes / 4) / (now - last) / 1e6,
                   (transfers - prior) * (bytes / 4) / (now - last) / 1e6, transfers);
            fflush(stdout);
            last = now; prior = transfers;
        }
    }
    double elapsed = now_seconds() - start;
    double word_rate = transfers * (bytes / 4) / elapsed / 1e6;
    printf("Total: %.2f Mword/s (~%.2f MHz CLK average from submissions, NOT a scope measurement)\n",
           word_rate, word_rate);
    if (divider <= 16 && word_rate < 1.0) {
        fputs("DMA did not make progress: possible stalled RP1 DMA channel."
              " Check dmesg for 'dma2chan0 is non-idle'.\n", stderr);
        goto done;
    }
    // TX ioctl only queues DMA. Give the four queued buffers time to finish
    // before disabling the SM, otherwise the driver may fail to stop DMA.
    double drain = (double)bytes * divider * 3 / 200e6 * 2 + 0.25;
    double deadline = now_seconds() + drain;
    while (now_seconds() < deadline) {
        struct timespec wait = { .tv_sec = 0, .tv_nsec = 10000000 };
        nanosleep(&wait, NULL);
    }
    result = 0;

done:
    if (initialized) {
        struct rp1_pio_sm_set_enabled_args off = {
            .mask = (uint16_t)(1u << sm), .enable = 0
        };
        command(fd, PIO_IOC_SM_SET_ENABLED, &off, "disable SM");
    }
    if (muxed_mask) {
        struct rp1_pio_sm_set_pins_args blank = {
            .sm = (uint16_t)sm, .values = OE_MASK, .mask = output_mask
        };
        command(fd, PIO_IOC_SM_SET_PINS, &blank, "blank outputs");
        struct rp1_pio_sm_set_pindirs_args input = {
            .sm = (uint16_t)sm, .dirs = 0, .mask = muxed_mask
        };
        command(fd, PIO_IOC_SM_SET_PINDIRS, &input, "release pin directions");
        for (unsigned pin = 0; pin < RP1_PIO_GPIO_COUNT; ++pin) {
            if (!(muxed_mask & (1u << pin))) continue;
            struct rp1_gpio_set_function_args release = {
                .gpio = (uint16_t)pin, .fn = 0x1f // GPIO_FUNC_NULL
            };
            command(fd, PIO_IOC_GPIO_SET_FUNCTION, &release, "release GPIO mux");
        }
    }
    if (loaded) {
        struct rp1_pio_remove_program_args remove = {
            .num_instrs = program.num_instrs, .origin = program.origin
        };
        command(fd, PIO_IOC_REMOVE_PROGRAM, &remove, "REMOVE_PROGRAM");
    }
    if (claimed) {
        claim.mask = 1u << sm;
        command(fd, PIO_IOC_SM_UNCLAIM, &claim, "SM_UNCLAIM");
    }
    close(fd);
    free(data);
    return result;

usage:
    fprintf(stderr, "Usage: %s [seconds=5] [divider=4] [KiB/transfer=256] [--output] [--light-dma]\n"
                    "Default is NO GPIO. --output: disconnect panels first; CLK17, 18 RGB, OE18 HIGH.\n", 
            argv[0]);
    return 2;
}
